"""Six localized generic guide edits; every other byte/line remains unchanged."""
import datetime,hashlib,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];guide=ROOT/'competition/skills/build-phone-agent.md'
def digest(b):return hashlib.sha256(b).hexdigest()
before=guide.read_bytes();lines=before.splitlines(keepends=True);replacements=[]
def change(anchor,old,new,reason,source_proof):
 hits=[i for i,line in enumerate(lines) if line.decode('utf-8').startswith(anchor)]
 assert len(hits)==1
 i=hits[0];original=lines[i].decode('utf-8');assert original.count(old)==1
 modified=original.replace(old,new);lines[i]=modified.encode('utf-8')
 replacements.append({'line':i+1,'reason':reason,'source_proof':source_proof,'before':original.rstrip('\r\n'),'after':modified.rstrip('\r\n')})
change('Use simple, phase-specific extraction','A richer event grammar may still serve the financial phases.','A richer event grammar may still serve the financial phases. Supply the opening extractor with the current call\'s configured first name, family name and title, and bind security extraction to the current requested field and answer revision. Do not supply expected security answers or pre-verification account facts. The producer must have the neutral context needed to distinguish a matching recipient from an explicitly different person; consumer matching remains permissive and bank verification remains separate.','Make producer recipient/field context explicit without adding debt or expected answers.','Verified Opus A1; actual listen description supplies phase/now/account_facts but omits called name/title; old recipient source failures are already covered by existing permissive consumer rules.')
change('Normalize complete payment-date values','Keep all policy calendar/window checks after normalization.','Keep all policy calendar/window checks after normalization. Apply the supplied policy\'s shared-date rule to a positively supported common-date assertion regardless of whether its targets are encoded as a collective alias or an explicit target list. Do not infer a shared proposal merely because independent product dates happen to be equal. State any policy-required date substitution in the readback, retaining each unaffected target\'s date.','Preserve semantic common-date scope across equivalent producer encodings.','CPU shared-date/all versus cpu-card,cpu-loan; original Brief B rule6; other briefs may use a different shared-date rule.')
change("Accumulate a turn's nonconflicting component rows",'Preserve explicit correction order and clarify conflicting values; do not silently choose a value merely because it appears last in the serialized extraction.','Preserve explicit correction order and clarify conflicting values; do not silently choose a value merely because it appears last in the serialized extraction. When corrections or retargeting require ordering, include source clause positions and explicit replacement relationships in the paired producer/decoder contract, and validate them against the actual speech. An explicit later replacement supersedes only that target/component. Moving a proposal to another target clears its old uncommitted terms only when that move is actually asserted; unrelated proposals and recorded effects remain. Missing or contradictory replacement evidence requires clarification.','Give existing correction-order requirement a concrete source-bound contract.','Opus A2; unordered same-target conflict control safely rejects; current producer has no order/replacement field. No ordering is inferred from row serialization.')
change('Represent the unresolved component explicitly','Only an explicit completed customer amount resolves that flag.','Resolve that flag only from an explicit completed customer amount or, where the input policy permits it, an unambiguous acceptance of a newly spoken recovery offer for this same target and revision. Such acceptance adopts the exact spoken amount, not a cached full balance or an unrelated floor. A later date-only reply cannot manufacture that acceptance. Fresh complete readback and subsequent confirmation remain required.','Remove contradiction with the existing policy-permitted agent recovery-offer branch.','Static guide conflict: this paragraph required a customer-spoken amount while the later forbidden-amount-question paragraph permits a fresh supported agent offer and its acceptance; Brief A rules24,26,27.')
change('API bodies must match','`maxRetries=0` on writing tools.','`maxRetries=0` on writing tools. Derive retry budgets by operation and documented error class from the input policy and API; a payment retry rule does not grant retries for every other operation. A documented unreadable-input rejection requires corrected input rather than an unchanged resend and is not a failed identity comparison. Distinguish it from a documented service failure where nothing was recorded. Do not invent error-code meanings, bank failures or receipts from a parser failure.','Separate operation-specific retries and application validation rejection from service failure.','Opus A3; synthetic identity/unreadable-not-retried-unchanged counterexample; OpenAPI verify_identity.answer says unreadable ok=false is not counted as a wrong answer. No actual backend frequency claim.')
change('Withdrawing provisional permission','Remove consent, preserve independently valid proposed terms and offer no replacement date or persuasion attempt solely because permission was withdrawn.','Remove consent, preserve independently valid proposed terms and offer no replacement date or persuasion attempt solely because permission was withdrawn. Scope withdrawal to its actual operations and targets while still retaining valid sibling facts from the same turn. Cancelling a payment promise does not erase an independently supported paid/dispute claim or cancel a note required by the supplied policy. Conversely, assent to adding a note is never permission to create a promise. Note bodies contain only the target, supported reason and policy-required information; exclude security-answer operands and unnecessary raw speech. Preserve all source-defined no-note transfer paths.','Separate promise permission from independent mandatory note basis and same-turn sibling proposals.','CPU mixed scoped-withdraw retains no sibling proposal; selected promise-withdraw+paid claim loses paid basis while paid-only control retains it; Brief B rules8-10. Forced note-assent-confirm is already covered by generic operation consent and is retained as a negative control.')
after=b''.join(lines)
assert len(before.splitlines())==len(after.splitlines())
assert before.count(b'\r\n')==after.count(b'\r\n') and before.count(b'\n')==after.count(b'\n')
assert guide.read_bytes()==before,'Guide changed concurrently'
guide.write_bytes(after)
report={'status':'GUIDE_ONLY_GENERIC_CLASSIC_R_AND_D_EDITS','created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'guide_before_sha256':digest(before),'guide_after_sha256':digest(after),'edited_lines':[r['line'] for r in replacements],'line_count_preserved':True,'line_endings_preserved':True,'all_other_lines_unchanged':all(a==b for i,(a,b) in enumerate(zip(before.splitlines(keepends=True),after.splitlines(keepends=True)),1) if i not in {r['line'] for r in replacements}),'edits':replacements,'limits':'Instruction changes only; no regenerated candidate, model changes, original pack/scorer changes or hosted score claim.'}
(ROOT/'analysis/classic-v2-opus.edits.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps({k:v for k,v in report.items() if k!='edits'}))
